'use client'

import React from 'react'
import { Edit, Trash2, Eye } from 'lucide-react'

import Image from 'next/image'
import { Blog } from '../../../../../types/blog'

interface BlogTableProps {
  blogs: Blog[]
  onView: (blog: Blog) => void
  onEdit: (blog: Blog) => void
  onDelete: (blogId: string) => void
  isLoading?: boolean
}

export default function BlogTable({
  blogs,
  onView,
  onEdit,
  onDelete,
  isLoading,
}: BlogTableProps) {
  if (isLoading) {
    return <div className="text-center py-8">Loading blogs...</div>
  }

  if (!blogs || blogs.length === 0) {
    return <div className="text-center py-8 text-gray-500">No blogs found</div>
  }

  return (
    <div className="overflow-x-auto">
      <table className="w-full">
        <thead className="bg-gray-50 border-b">
          <tr>
            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
              Image
            </th>
            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
              Title
            </th>
            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
              Read Time
            </th>
            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
              Status
            </th>
            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
              Tags
            </th>
            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
              Date
            </th>
            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
              Actions
            </th>
          </tr>
        </thead>
        <tbody className="bg-white divide-y divide-gray-200">
          {blogs.map((blog) => (
            <tr key={blog._id} className="hover:bg-gray-50">
              <td className="px-6 py-4">
                <div className="w-16 h-16 relative">
                  {blog.uploadPhoto ? (
                    <Image
                      src={blog.uploadPhoto}
                      alt={blog.title}
                      fill
                      className="object-cover rounded"
                    />
                  ) : (
                    <div className="w-full h-full bg-gray-200 rounded flex items-center justify-center text-gray-400">
                      No Image
                    </div>
                  )}
                </div>
              </td>
              <td className="px-6 py-4">
                <span className="font-medium text-gray-900">{blog.title}</span>
              </td>
              <td className="px-6 py-4 text-sm text-gray-500">
                {blog.readTime}
              </td>
              <td className="px-6 py-4">
                <span
                  className={`px-2 py-1 inline-flex text-xs leading-5 font-semibold rounded-full ${
                    blog.status === 'published'
                      ? 'bg-green-100 text-green-800'
                      : 'bg-yellow-100 text-yellow-800'
                  }`}
                >
                  {blog.status}
                </span>
              </td>
              <td className="px-6 py-4">
                <div className="flex flex-wrap gap-1">
                  {blog.tags && blog.tags.length > 0 ? (
                    blog.tags.slice(0, 2).map((tag, index) => (
                      <span
                        key={index}
                        className="px-2 py-1 bg-blue-100 text-blue-800 text-xs rounded"
                      >
                        {tag}
                      </span>
                    ))
                  ) : (
                    <span className="text-gray-400 text-xs">No tags</span>
                  )}
                  {blog.tags && blog.tags.length > 2 && (
                    <span className="text-xs text-gray-500">
                      +{blog.tags.length - 2}
                    </span>
                  )}
                </div>
              </td>
              <td className="px-6 py-4 text-sm text-gray-500">
                {new Date(blog.createdAt).toLocaleDateString()}
              </td>
              <td className="px-6 py-4 text-sm">
                <div className="flex gap-2">
                  <button
                    onClick={() => onView(blog)}
                    className="text-blue-600 hover:text-blue-800"
                    title="View"
                  >
                    <Eye className="w-5 h-5" />
                  </button>
                  <button
                    onClick={() => onEdit(blog)}
                    className="text-green-600 hover:text-green-800"
                    title="Edit"
                  >
                    <Edit className="w-5 h-5" />
                  </button>
                  <button
                    onClick={() => {
                      if (
                        confirm('Are you sure you want to delete this blog?')
                      ) {
                        onDelete(blog._id)
                      }
                    }}
                    className="text-red-600 hover:text-red-800"
                    title="Delete"
                  >
                    <Trash2 className="w-5 h-5" />
                  </button>
                </div>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}
