'use client'

import React, { useState } from 'react'
import { Button } from '@/components/ui/button'
import { Card, CardContent } from '@/components/ui/card'
import { ChevronRight, Loader2 } from 'lucide-react'
import {
  useGetBlogs,
  useAddBlog,
  useUpdateBlog,
  useDeleteBlog,
  useGetSingleBlog,
} from '@/lib/blogApi'

import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import BlogForm, { BlogFormData } from './blogForm'
import BlogTable from './blogTable'

export default function BlogManagement() {
  const [currentPage, setCurrentPage] = useState(1)
  const [isFormOpen, setIsFormOpen] = useState(false)
  const [isDetailsOpen, setIsDetailsOpen] = useState(false)
  const [editingBlogId, setEditingBlogId] = useState<string | null>(null)
  const [viewingBlogId, setViewingBlogId] = useState<string | null>(null)

  // API Queries
  const { data: blogsData, isLoading: blogsLoading } = useGetBlogs(
    currentPage,
    10
  )
  const { data: singleBlogData } = useGetSingleBlog(
    editingBlogId || viewingBlogId || undefined
  )
  const { mutate: deleteBlog } = useDeleteBlog()

  const { mutate: addBlog, isPending: isAddingBlog } = useAddBlog({
    onSuccess: () => {
      setIsFormOpen(false)
      setEditingBlogId(null)
    },
  })

  const { mutate: updateBlog, isPending: isUpdatingBlog } = useUpdateBlog({
    onSuccess: () => {
      setIsFormOpen(false)
      setEditingBlogId(null)
    },
  })

  const handleAddBlog = () => {
    setEditingBlogId(null)
    setIsFormOpen(true)
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const handleEditBlog = (blog: any) => {
    setEditingBlogId(blog._id)
    setIsFormOpen(true)
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const handleViewBlog = (blog: any) => {
    setViewingBlogId(blog._id)
    setIsDetailsOpen(true)
  }

  const handleDeleteBlog = (blogId: string) => {
    deleteBlog(blogId)
  }

  const handleSubmitBlog = (data: BlogFormData, file?: File) => {
    if (editingBlogId) {
      // Update existing blog
      updateBlog({
        blogId: editingBlogId,
        data: {
          title: data.title,
          readTime: data.readTime,
          description: data.description,
          status: data.status,
          featured: data.featured,
        },
      })
    } else {
      // Add new blog
      const formData = new FormData()
      formData.append('title', data.title)
      formData.append('readTime', data.readTime)
      formData.append('description', data.description)
      formData.append('status', data.status)
      formData.append('featured', data.featured.toString())

      if (file) {
        formData.append('uploadPhoto', file)
      }

      addBlog(formData)
    }
  }

  const blogs = blogsData?.blogs || []
  const pagination = blogsData?.pagination

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-6">
          <div className="flex justify-between items-center mb-2">
            <h1 className="text-3xl font-bold text-gray-900">
              Blog Management
            </h1>
            <Button onClick={handleAddBlog} size="sm" className="h-[50px] px-6">
              + Add Blog
            </Button>
          </div>
          <div className="flex items-center text-sm text-gray-500">
            <span>Dashboard</span>
            <ChevronRight className="w-4 h-4 mx-2" />
            <span className="text-gray-900">Blog Management</span>
          </div>
        </div>

        {/* Table */}
        <Card>
          <CardContent className="p-0">
            <BlogTable
              blogs={blogs}
              onView={handleViewBlog}
              onEdit={handleEditBlog}
              onDelete={handleDeleteBlog}
              isLoading={blogsLoading}
            />

            {/* Pagination */}
            {pagination && (
              <div className="bg-white px-4 py-3 flex items-center justify-between border-t">
                <div className="text-sm text-gray-700">
                  Showing page {pagination.currentPage} of{' '}
                  {pagination.totalPages}({pagination.totalData} total)
                </div>
                <div className="flex gap-2">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
                    disabled={!pagination.hasPrevPage}
                  >
                    Previous
                  </Button>
                  {[...Array(pagination.totalPages)].map((_, i) => (
                    <Button
                      key={i}
                      variant={currentPage === i + 1 ? 'default' : 'outline'}
                      size="sm"
                      onClick={() => setCurrentPage(i + 1)}
                    >
                      {i + 1}
                    </Button>
                  ))}
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setCurrentPage((p) => p + 1)}
                    disabled={!pagination.hasNextPage}
                  >
                    Next
                  </Button>
                </div>
              </div>
            )}
          </CardContent>
        </Card>

        {/* Add/Edit Form Dialog */}
        <Dialog open={isFormOpen} onOpenChange={setIsFormOpen}>
          <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
            <DialogHeader>
              <DialogTitle>
                {editingBlogId ? 'Edit Blog' : 'Add New Blog'}
              </DialogTitle>
            </DialogHeader>
            <BlogForm
              blog={editingBlogId ? singleBlogData?.blog : null}
              onSubmit={handleSubmitBlog}
              onCancel={() => {
                setIsFormOpen(false)
                setEditingBlogId(null)
              }}
              isLoading={isAddingBlog || isUpdatingBlog}
            />
          </DialogContent>
        </Dialog>

        {/* View Details Dialog */}
        <Dialog open={isDetailsOpen} onOpenChange={setIsDetailsOpen}>
          <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
            <DialogHeader>
              <DialogTitle>Blog Details</DialogTitle>
            </DialogHeader>
            {singleBlogData?.blog && (
              <div className="space-y-4">
                <div>
                  <h3 className="text-2xl font-bold mb-2">
                    {singleBlogData.blog.title}
                  </h3>
                  <div className="flex gap-4 text-sm text-gray-500">
                    <span>📖 {singleBlogData.blog.readTime}</span>
                    <span>
                      📅{' '}
                      {new Date(
                        singleBlogData.blog.createdAt
                      ).toLocaleDateString()}
                    </span>
                    <span
                      className={`px-2 py-1 rounded ${
                        singleBlogData.blog.status === 'published'
                          ? 'bg-green-100 text-green-800'
                          : 'bg-yellow-100 text-yellow-800'
                      }`}
                    >
                      {singleBlogData.blog.status}
                    </span>
                    {singleBlogData.blog.featured && (
                      <span className="px-2 py-1 bg-blue-100 text-blue-800 rounded">
                        ⭐ Featured
                      </span>
                    )}
                  </div>
                </div>

                {singleBlogData.blog.uploadPhoto && (
                  <img
                    src={singleBlogData.blog.uploadPhoto}
                    alt={singleBlogData.blog.title}
                    className="w-full rounded-lg"
                  />
                )}

                <div>
                  <h4 className="font-semibold mb-2">Description</h4>
                  <div
                    className="prose max-w-none"
                    dangerouslySetInnerHTML={{
                      __html: singleBlogData.blog.description,
                    }}
                  />
                </div>
              </div>
            )}
          </DialogContent>
        </Dialog>
      </div>
    </div>
  )
}
