'use client'

import React, { useState, useEffect } from 'react'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Loader2, Upload, X } from 'lucide-react'
import TiptapEditor from './TiptapEditor'
import Image from 'next/image'
import { Blog } from '../../../../../types/blog'

const blogSchema = z.object({
  title: z.string().min(1, 'Title is required'),
  readTime: z.string().min(1, 'Read time is required'),
  description: z.string().min(1, 'Description is required'),
  status: z.enum(['draft', 'published']),
  tags: z.array(z.string()).min(1, 'At least one tag is required'),
})

export type BlogFormData = z.infer<typeof blogSchema>

interface BlogFormProps {
  blog?: Blog | null
  onSubmit: (data: BlogFormData, file?: File) => void
  onCancel: () => void
  isLoading?: boolean
}

export default function BlogForm({
  blog,
  onSubmit,
  onCancel,
  isLoading,
}: BlogFormProps) {
  const [imagePreview, setImagePreview] = useState<string>(
    blog?.uploadPhoto || ''
  )
  const [imageFile, setImageFile] = useState<File | null>(null)
  const [tagInput, setTagInput] = useState('')
  const [tags, setTags] = useState<string[]>(blog?.tags || [])

  const {
    register,
    handleSubmit,
    setValue,
    watch,
    reset,
    formState: { errors },
  } = useForm<BlogFormData>({
    resolver: zodResolver(blogSchema),
    defaultValues: {
      title: '',
      readTime: '',
      description: '',
      status: 'draft',
      tags: [],
    },
  })

  useEffect(() => {
    if (blog) {
      reset({
        title: blog.title || '',
        readTime: blog.readTime || '',
        description: blog.description || '',
        status: blog.status || 'draft',
        tags: blog.tags || [],
      })
      setImagePreview(blog.uploadPhoto || '')
      setTags(blog.tags || [])
    }
  }, [blog, reset])

  useEffect(() => {
    setValue('tags', tags)
  }, [tags, setValue])

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (file) {
      setImageFile(file)
      const reader = new FileReader()
      reader.onloadend = () => {
        setImagePreview(reader.result as string)
      }
      reader.readAsDataURL(file)
    }
  }

  const removeImage = () => {
    setImagePreview('')
    setImageFile(null)
  }

  const handleAddTag = () => {
    if (tagInput.trim() && !tags.includes(tagInput.trim())) {
      const newTags = [...tags, tagInput.trim()]
      setTags(newTags)
      setTagInput('')
    }
  }

  const handleRemoveTag = (tagToRemove: string) => {
    setTags(tags.filter((tag) => tag !== tagToRemove))
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault()
      handleAddTag()
    }
  }

  const onFormSubmit = (data: BlogFormData) => {
    onSubmit(data, imageFile || undefined)
  }

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div>
          <Label htmlFor="title">Title</Label>
          <Input
            id="title"
            placeholder="Enter blog title..."
            {...register('title')}
            className="mt-1"
          />
          {errors.title && (
            <p className="text-red-500 text-sm mt-1">{errors.title.message}</p>
          )}
        </div>

        <div>
          <Label htmlFor="readTime">Read Time</Label>
          <Input
            id="readTime"
            placeholder="e.g., 5 min read"
            {...register('readTime')}
            className="mt-1"
          />
          {errors.readTime && (
            <p className="text-red-500 text-sm mt-1">
              {errors.readTime.message}
            </p>
          )}
        </div>
      </div>

      <div>
        <Label>Description</Label>
        <div className="mt-1">
          <TiptapEditor
            content={watch('description')}
            onChange={(content) => setValue('description', content)}
          />
        </div>
        {errors.description && (
          <p className="text-red-500 text-sm mt-1">
            {errors.description.message}
          </p>
        )}
      </div>

      <div>
        <Label>Tags</Label>
        <div className="flex gap-2 mt-1">
          <Input
            value={tagInput}
            onChange={(e) => setTagInput(e.target.value)}
            onKeyPress={handleKeyPress}
            placeholder="Add a tag..."
          />
          <Button type="button" onClick={handleAddTag} variant="outline">
            Add
          </Button>
        </div>
        <div className="flex flex-wrap gap-2 mt-2">
          {tags.map((tag) => (
            <span
              key={tag}
              className="px-3 py-1 bg-blue-100 text-blue-800 rounded-full text-sm flex items-center gap-1"
            >
              {tag}
              <button
                type="button"
                onClick={() => handleRemoveTag(tag)}
                className="hover:text-red-600"
              >
                <X className="w-3 h-3" />
              </button>
            </span>
          ))}
        </div>
        {errors.tags && (
          <p className="text-red-500 text-sm mt-1">{errors.tags.message}</p>
        )}
      </div>

      <div>
        <Label>Upload Photo</Label>
        <div className="border-2 border-dashed rounded-lg p-6 text-center mt-1">
          {imagePreview ? (
            <div className="relative inline-block">
              <Image
                src={imagePreview}
                alt="Preview"
                width={200}
                height={200}
                className="max-h-48 rounded"
              />
              <button
                type="button"
                onClick={removeImage}
                className="absolute top-2 right-2 bg-red-500 text-white rounded-full p-1"
              >
                <X className="w-4 h-4" />
              </button>
            </div>
          ) : (
            <div>
              <Upload className="w-12 h-12 mx-auto text-gray-400 mb-2" />
              <p className="text-sm text-gray-500 mb-2">
                Click to upload image
              </p>
              <input
                type="file"
                accept="image/*"
                onChange={handleImageUpload}
                className="hidden"
                id="blog-image"
              />
              <Button
                type="button"
                variant="outline"
                onClick={() => document.getElementById('blog-image')?.click()}
              >
                Choose File
              </Button>
            </div>
          )}
        </div>
      </div>

      <div>
        <Label htmlFor="status">Status</Label>
        <select
          {...register('status')}
          className="w-full px-3 py-2 border rounded-md mt-1"
        >
          <option value="draft">Draft</option>
          <option value="published">Published</option>
        </select>
      </div>

      <div className="flex justify-end gap-3 pt-4 border-t">
        <Button
          type="button"
          variant="outline"
          onClick={onCancel}
          disabled={isLoading}
        >
          Cancel
        </Button>
        <Button onClick={handleSubmit(onFormSubmit)} disabled={isLoading}>
          {isLoading ? (
            <>
              <Loader2 className="w-4 h-4 mr-2 animate-spin" />
              Saving...
            </>
          ) : blog ? (
            'Update Blog'
          ) : (
            'Create Blog'
          )}
        </Button>
      </div>
    </div>
  )
}
